/**
 * The app instance. ForgeKit's `ForgeHost` opens one per process.
 */
public protocol AppCoreProtocol: AnyObject, Sendable {
    
    /**
     * Subscribes to the feed at `url` (`https://` is assumed when no scheme
     * is given; `feed://` means `https://`): fetches it, checks it is a
     * feed, and saves it with its articles. On-screen work until it is
     * saved: `cancellation`, the background or shutdown stop the fetch.
     */
    func addFeed(url: String, cancellation: Cancellation?) async throws  -> Feed
    
    /**
     * One article's row, or nil once its feed is gone.
     */
    func article(id: Int64)  -> ArticleSummary?
    
    /**
     * The host's background time ran out: finishing work stops.
     */
    func backgroundTimeExpired() 
    
    /**
     * Whether commands or finishing work are still running; the
     * host holds background time while they are.
     */
    func backgroundWorkPending()  -> Bool
    
    /**
     * How many articles a timeline holds and how many of them are unread.
     */
    func counts(timeline: Timeline)  -> TimelineCounts
    
    /**
     * The runtime's event stream: `Changed { revision }` after each
     * committed command, phase changes, and drops. Nil after shutdown.
     */
    func events()  -> RuntimeEvents?
    
    /**
     * Every subscription, by title.
     */
    func feeds()  -> [Feed]
    
    /**
     * What the runtime found at open (unfinished background work).
     */
    func launchReport()  -> LaunchReport
    
    /**
     * Marks every article of one feed (or of every feed, with nil) read.
     * Returns how many changed.
     */
    func markAllRead(feedId: Int64?) async throws  -> UInt32
    
    /**
     * Opens an article for reading: marks it read and returns its text.
     */
    func openArticle(articleId: Int64) async throws  -> ArticleText
    
    /**
     * The phase last reported.
     */
    func phase()  -> AppPhase
    
    /**
     * Fetches every feed (conditionally: unchanged feeds cost one small
     * request) and saves what is new. One feed failing doesn't stop the
     * others; each failure is in the report and on the feed. On-screen
     * work: stopped by `cancellation`, the background or shutdown, in
     * which case nothing is saved.
     */
    func refresh(cancellation: Cancellation?) async throws  -> RefreshReport
    
    /**
     * Unsubscribes, deleting the feed's articles (bookmarked ones too).
     */
    func removeFeed(feedId: Int64) async throws 
    
    /**
     * Gives a feed the person's own name; blank goes back to the feed's.
     */
    func renameFeed(feedId: Int64, title: String) async throws 
    
    /**
     * The last committed revision.
     */
    func revision()  -> UInt64
    
    func setBookmarked(articleId: Int64, bookmarked: Bool) async throws 
    
    /**
     * The host reports the application lifecycle phase.
     */
    func setPhase(phase: AppPhase) 
    
    func setRead(articleId: Int64, read: Bool) async throws 
    
    /**
     * Refuses new commands, stops work in flight and ends event
     * streams. Commands already accepted still finish and save.
     */
    func shutdown() 
    
    /**
     * The articles a timeline shows, newest first.
     */
    func timeline(timeline: Timeline)  -> [ArticleSummary]
    
}
