/**
 * Every error the API returns. `reason` fields are diagnostics, not UI copy.
 */
public 
enum AppError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case InvalidInput(reason: String
    )
    case NotFound
    /**
     * Already subscribed to this address.
     */
    case AlreadySubscribed(feedId: Int64
    )
    /**
     * The address answered, but not with an RSS, Atom or JSON feed.
     */
    case NotAFeed(reason: String
    )
    /**
     * The server answered with an HTTP error.
     */
    case Http(status: UInt16
    )
    case Storage(reason: String
    )
    case InUse
    case Offline(reason: String
    )
    case Certificate(reason: String
    )
    case Timeout
    case Network(reason: String
    )
    case Cancelled
    case Interrupted
    case ShutDown

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension AppError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAppError: FfiConverterRustBuffer {
    typealias SwiftType = AppError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AppError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidInput(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 2: return .NotFound
        case 3: return .AlreadySubscribed(
            feedId: try FfiConverterInt64.read(from: &buf)
            )
        case 4: return .NotAFeed(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Http(
            status: try FfiConverterUInt16.read(from: &buf)
            )
        case 6: return .Storage(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 7: return .InUse
        case 8: return .Offline(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 9: return .Certificate(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 10: return .Timeout
        case 11: return .Network(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 12: return .Cancelled
        case 13: return .Interrupted
        case 14: return .ShutDown

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AppError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidInput(reason):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(reason, into: &buf)
            
        
        case .NotFound:
            writeInt(&buf, Int32(2))
        
        
        case let .AlreadySubscribed(feedId):
            writeInt(&buf, Int32(3))
            FfiConverterInt64.write(feedId, into: &buf)
            
        
        case let .NotAFeed(reason):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Http(status):
            writeInt(&buf, Int32(5))
            FfiConverterUInt16.write(status, into: &buf)
            
        
        case let .Storage(reason):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(reason, into: &buf)
            
        
        case .InUse:
            writeInt(&buf, Int32(7))
        
        
        case let .Offline(reason):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Certificate(reason):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(reason, into: &buf)
            
        
        case .Timeout:
            writeInt(&buf, Int32(10))
        
        
        case let .Network(reason):
            writeInt(&buf, Int32(11))
            FfiConverterString.write(reason, into: &buf)
            
        
        case .Cancelled:
            writeInt(&buf, Int32(12))
        
        
        case .Interrupted:
            writeInt(&buf, Int32(13))
        
        
        case .ShutDown:
            writeInt(&buf, Int32(14))
        
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
